let embeddedRule0145: RuleEntry = RuleEntry(
    id: "dmg_ch10_magical_item_tables",
    book: "DMG",
    chapterNumber: 10,
    chapterTitle: "Treasure and Magical Items (Mechanics)",
    breadcrumbs: "Dungeon Master's Guide > Chapter 10: Treasure and Magical Items (Mechanics) > Magical Item Tables",
    topic: "Magical Item Tables",
    ruleType: "dm_guideline",
    summary: "When possible, the DM should select the magical items he gives out in his campaign. Sometimes, however, the DM has more pressing game matters on his mind. To determine randomly what magical item has been found, roll on Table 88.",
    content: "When possible, the DM should select the magical items he gives out in his campaign. Sometimes, however, the DM has more pressing game matters on his mind. To determine randomly what magical item has been found, roll on Table 88. This table directs you to one of the specific categories in Tables 89-108.\n\nItems followed by a group name are usable only by characters of that group.\n\nNote: XP Value is the number of experience points a character gets for making an item.\n\nOnce the general category is determined, the DM can choose a specific item from the tables below. (Each item on the tables is given a die roll number so that the DM can select items randomly, if he chooses.) Some tables have several subtables. Each subtable has a range of numbers in parentheses at the top. To select the appropriate subtable, check the die listed after the table's title. Roll the listed die and find the result in the number range at the top of one of the subtables. This is the subtable you read to determine which item in the list has been found.\n\nFor example, the Potions and Oils table has \"(D6)\" after the title. That means you roll a 6-sided die to determine which Subtable (A, B, or C) to read. If you roll a 2, for example, you check subtable A (which has \"1-2\" at the top); if you roll a 6, you read subtable C (which has \"5-6\" at the top). Roll 1d20 on the appropriate subtable to determine the specific item found. Then turn to the descriptions following the tables to find out what each item does.\n\n[TABLE_REF: Table 88: Magical Items]",
    tables: [
        RuleTable(
                tableNumber: "Table 88",
                title: "Table 88: Magical Items",
                headers: ["D20 Roll", "Category"],
                rows: [
                    ["01-20", "Table 89: Potions and Oils"],
                    ["21-35", "Table 90: Scrolls"],
                    ["36-40", "Table 91: Rings"],
                    ["41", "Table 92: Rods"],
