                    ["43-45", "Table 94: Wands"],
                    ["46", "Table 95: Miscellaneous Magic: Books and Tomes"],
                    ["47-48", "Table 96: Miscellaneous Magic: Jewels and Jewelry"],
                    ["49-50", "Table 97: Miscellaneous Magic: Cloaks and Robes"],
                    ["51-52", "Table 98: Miscellaneous Magic: Boots and Gloves"],
                    ["53", "Table 99: Miscellaneous Magic: Girdles and Helms"],
                    ["54-55", "Table 100: Miscellaneous Magic: Bags and Bottles"],
                    ["56", "Table 101: Miscellaneous Magic: Dusts and Stones"],
                    ["57", "Table 102: Miscellaneous Magic: Household Items and Tools"],
                    ["58", "Table 103: Miscellaneous Magic: Musical Instruments"],
                    ["59-60", "Table 104: Miscellaneous Magic: The Weird Stuff"],
                    ["61-75", "Table 105: Armor and Shields"],
                    ["76-100", "Table 108: Weapons"]
