let embeddedRule0152: RuleEntry = RuleEntry(
    id: "dmg_ch10_staves",
    book: "DMG",
    chapterNumber: 10,
    chapterTitle: "Treasure and Magical Items (Mechanics)",
    breadcrumbs: "Dungeon Master's Guide > Chapter 10: Treasure and Magical Items (Mechanics) > Staves",
    topic: "Staves",
    ruleType: "optional_rule",
    summary: "**Staves** are about 5 feet or 6 feet long and as thick as a young sapling—about an inch and a half at the base, tapering to an inch at the tip, although they can be of nearly equal diameter throughout.",
    content: "**Staves** are about 5 feet or 6 feet long and as thick as a young sapling—about an inch and a half at the base, tapering to an inch at the tip, although they can be of nearly equal diameter throughout. Staves are typically fashioned of wood, often carved, usually metal bound, and likely to be gnarly and twisted. They can be unusual or appear to be ordinary.\n\nStaves, like wands and rods, are powered by charges. A staff typically has 1d6+19 charges when found. Again, it is possible for a stave to have fewer charges, although almost none have more than this number. Some staves can be recharged according to the rules for making magical items. Once all the charges are used, the stave is rendered nonmagical and cannot be recharged.\n\nUnless inapplicable or otherwise specified, staves function at the 8th level of magic use. Their spell discharge is that of an 8th-level wizard with respect to range, duration, and area of effect.\nDamage is nominally 8d6 with respect to fireballs, lightning bolts, etc.\n\n## Command Words (Optional Rule)\nIf the DM desires, unleashing the power of a stave can require a specific command word or phrase that must be discovered or researched separately from the item itself. This command can be as simple as a single word (\"Heal'') or could be as complicated as a rhyming phrase that must be adjusted to fit the circumstances (\"I touch this elf; restore his health,\" or \"In this moment of great toil, I command thee, staff—uncoil!\"). Since command words are the key to great power, wise owners will memorize them and destroy all other evidence. Indeed, knowledge of command words can be used as a bargaining point in surrender negotiations.",
    tables: [],
    relatedRuleIds: [],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["damage", "staves"]
)

let embeddedRule0153: RuleEntry = RuleEntry(
    id: "dmg_ch10_wands",
    book: "DMG",
    chapterNumber: 10,
    chapterTitle: "Treasure and Magical Items (Mechanics)",
    breadcrumbs: "Dungeon Master's Guide > Chapter 10: Treasure and Magical Items (Mechanics) > Wands",
    topic: "Wands",
    ruleType: "optional_rule",
    summary: "**Wands** are feet long and slender. They are made of ivory, bone, or wood and are usually tipped with something—metal, crystal, stone, etc. They are fragile and tend to break easily. Because of this, they are often kept in cases.",
    content: "**Wands** are  feet long and slender. They are made of ivory, bone, or wood and are usually tipped with something—metal, crystal, stone, etc. They are fragile and tend to break easily. Because of this, they are often kept in cases.\n\nWands perform at 6th level of experience with respect to the damage they cause, range, duration, area of effect, etc., unless otherwise stated.\n\nAt the DM's option, 1% of all wands can be trapped to backfire.\n\nWands are powered by charges, each use costing one or more charges (depending on the item). When discovered, a wand typically contains 1d20+80 charges. Captured wands taken from a defeated foe often have many fewer charges. Wands never have a greater number of charges than those listed. Most wands can be recharged according to the rules for making magical items.\n\nWhen a wand runs out of charges, it can no longer be recharged. Furthermore, the DM can rule that the wand immediately crumbles into useless dust (settling the issue) or is now a useless, nonmagical stick.\n\n## Command Words (Optional Rule)\nLike rods and staves, wands can require the utterance of a command word (or phrase) to operate, and like these other items, the key is seldom found in the lock. The DM can rule that the command word is etched in magical writing on the wand (requiring a *read magic* to translate) or he can make the characters resort to such methods as *commune* spells and expensive sages. If you choose not to use this option, ignore references to command words in the item descriptions below—all items simply work.",
    tables: [],
    relatedRuleIds: [],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["damage", "wands"]
)
